package com.example.billing.api;import static com.example.billing.api.Contracts.*;import com.example.billing.service.SubscriptionService;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController public class SubscriptionController{private final SubscriptionService s;public SubscriptionController(SubscriptionService s){this.s=s;}@PostMapping("/subscriptions")ResponseEntity<?> create(@RequestBody CreateSubscriptionRequest r){try{var x=s.create(r);return ResponseEntity.created(URI.create("/subscriptions/"+x.id())).body(x);}catch(IllegalStateException e){return bad("customer_not_found",e);}catch(IllegalArgumentException e){return bad("price_plan_not_found",e);}catch(UnsupportedOperationException e){return bad("billing_interval_not_supported",e);}}@GetMapping("/subscriptions/{id}")ResponseEntity<?> get(@PathVariable UUID id){var x=s.get(id);return x==null?CatalogController.notFound("subscription_not_found","Subscription does not exist."):ResponseEntity.ok(x);}@GetMapping("/customers/{id}/subscriptions")List<SubscriptionResponse> list(@PathVariable UUID id){return s.list(id);}@PostMapping("/subscriptions/{id}/cancel")ResponseEntity<?> cancel(@PathVariable UUID id,@RequestBody CancelSubscriptionRequest r){var x=s.cancel(id,r);return x==null?CatalogController.notFound("subscription_not_found","Subscription does not exist."):ResponseEntity.ok(x);}@PostMapping("/subscriptions/{id}/change-plan")ResponseEntity<?> change(@PathVariable UUID id,@RequestBody ChangeSubscriptionPlanRequest r){try{var x=s.changePlan(id,r);return x==null?CatalogController.notFound("subscription_not_found","Subscription does not exist."):ResponseEntity.ok(x);}catch(IllegalArgumentException e){return bad("price_plan_not_found",e);}catch(IllegalStateException e){return bad("subscription_not_active",e);}catch(UnsupportedOperationException e){return bad("billing_interval_not_supported",e);}}private static ResponseEntity<ApiError> bad(String c,Exception e){return ResponseEntity.badRequest().body(new ApiError(c,e.getMessage()));}}
